export type Messages = typeof messages.en;
export function getMessages(locale: Locale): Messages {
    if (locale === 'en') return messages.en;
    const merge = (base: Record<string, unknown>, translated: Record<string, unknown>): Record<string, unknown> => {
        const result = { ...base };
        for (const [key, value] of Object.entries(translated)) {
            const original = result[key];
            result[key] = value && original && typeof value === 'object' && typeof original === 'object'
                ? merge(original as Record<string, unknown>, value as Record<string, unknown>)
                : value;
        }
        return result;
    };
    return merge(messages.en, messages[locale]) as Messages;
}
export function isLocale(value: string | undefined | null): value is Locale {
    return !!value && (locales as readonly string[]).includes(value);
}

